SELECT x.queue, x.run, x.body,
  json_patch(json_patch('{}', json_object('item', x.item, 'sha', x.sha, 'enqueued', x.enqueued, 'repo', x.repo, 'mode', x.mode, 'state', x.state, 'attempt', x.attempt, 'requested', x.requested, 'started', x.started, 'finished', x.finished, 'k', x.k, 'landed', x.landed, 'log', x.log, 'why', x.why, 'stage', x.stage, 'cause', x.cause, 'cause_detail', x.cause_detail, 'k_why', x.k_why, 'pre_affected', CASE WHEN coalesce(x.pre_affected_ran, x.pre_affected_took, x.pre_affected_by, x.pre_affected_lane_s, x.pre_affected_tests) IS NOT NULL THEN json_object('ran', x.pre_affected_ran, 'took', x.pre_affected_took, 'by', x.pre_affected_by, 'lane_s', x.pre_affected_lane_s, 'tests', x.pre_affected_tests) END, 'batch', CASE WHEN coalesce(x.batch, x.batch_items, x.batch_gates) IS NOT NULL THEN json_object('id', x.batch, 'items', x.batch_items, 'gates', x.batch_gates) END, 'pre_run', CASE WHEN coalesce(x.pre_run_skipped, coalesce(x.remote_outcome, x.remote_cause, x.remote_where, x.remote_host, x.remote_worker_s, x.remote_mac_s, x.remote_mac_est_s, x.remote_rerun_s, x.remote_saved_s, x.remote_t0, x.remote_tests, x.remote_fresh), x.pre_run_wait_s, x.pre_run_run_s, x.pre_run_limit_s, x.pre_run_cpu_s, x.pre_run_workers) IS NOT NULL THEN json_object('skipped', x.pre_run_skipped, 'remote', CASE WHEN coalesce(x.remote_outcome, x.remote_cause, x.remote_where, x.remote_host, x.remote_worker_s, x.remote_mac_s, x.remote_mac_est_s, x.remote_rerun_s, x.remote_saved_s, x.remote_t0, x.remote_tests, x.remote_fresh) IS NOT NULL THEN json_object('outcome', x.remote_outcome, 'cause', x.remote_cause, 'where', x.remote_where, 'host', x.remote_host, 'worker_s', x.remote_worker_s, 'mac_s', x.remote_mac_s, 'mac_est_s', x.remote_mac_est_s, 'rerun_s', x.remote_rerun_s, 'saved_s', x.remote_saved_s, 't0', x.remote_t0, 'tests', x.remote_tests, 'fresh', CASE x.remote_fresh WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'wait_s', x.pre_run_wait_s, 'run_s', x.pre_run_run_s, 'limit_s', x.pre_run_limit_s, 'cpu_s', x.pre_run_cpu_s, 'workers', x.pre_run_workers) END, 'red_cause', CASE WHEN coalesce(x.red_class, x.red_rule, (SELECT 1 FROM land_lists c WHERE c.queue = x.queue AND c.run = x.run AND c.kind = 'red_test' LIMIT 1)) IS NOT NULL THEN json_object('cause', x.red_class, 'rule', x.red_rule, 'tests', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = x.queue AND c.run = x.run AND c.kind = 'red_test'), '[]'), '{}'))) END, 'diffcov_item', CASE WHEN coalesce(x.diffcov_item, x.diffcov_said) IS NOT NULL THEN json_object('id', x.diffcov_item, 'said', x.diffcov_said) END, 'cov_risk', CASE WHEN coalesce(x.cov_said, x.cov_head, x.cov_base, x.cov_lines, (SELECT 1 FROM land_cov_carry c WHERE c.queue = x.queue AND c.run = x.run LIMIT 1), (SELECT 1 FROM land_cov_files c WHERE c.queue = x.queue AND c.run = x.run LIMIT 1)) IS NOT NULL THEN json_object('said', x.cov_said, 'head', x.cov_head, 'base', x.cov_base, 'lines', x.cov_lines, 'carry', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('file', c.file, 'text', c.text, 'why', c.why, 'line', c.line, 'own', CASE c.own WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'measured', CASE c.measured WHEN 1 THEN json('true') WHEN 0 THEN json('false') END)) ORDER BY c.ord) FROM land_cov_carry c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}')), 'files', json(nullif(nullif((SELECT json_group_object(c.path, c.said) FROM land_cov_files c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}'))) END, 'pre_s', x.pre_s, 'slot_s', x.slot_s, 'slot_wait_s', x.slot_wait_s, 'load_start', x.load_start, 'load_end', x.load_end, 'slot_wait_by_class', CASE WHEN coalesce(x.slot_wait_short_s, x.slot_wait_land_s, x.slot_wait_pre_s, x.slot_wait_work_s) IS NOT NULL THEN json_object('short', x.slot_wait_short_s, 'land', x.slot_wait_land_s, 'pre', x.slot_wait_pre_s, 'work', x.slot_wait_work_s) END, 'early', CASE x.early WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'recorded', CASE x.recorded WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'guards', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = x.queue AND c.run = x.run AND c.kind = 'guard'), '[]'), '{}')), 'red_logs', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = x.queue AND c.run = x.run AND c.kind = 'red_log'), '[]'), '{}')), 'flakes', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('test', c.test, 'entry', c.entry, 'filed', c.filed)) ORDER BY c.ord) FROM land_flakes c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}')), 'remote_shares', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('host', c.host, 'outcome', c.outcome, 'where', c.place, 'mac_est_s', c.mac_est_s, 'mac_s', c.mac_s, 'rerun_s', c.rerun_s, 'saved_s', c.saved_s, 't0', c.t0, 'worker_s', c.worker_s, 'tests', c.tests)) ORDER BY c.ord) FROM land_remote_shares c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}')), 'cap_items', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('id', c.id, 'file', c.file, 'said', c.said, 'lines', c.lines)) ORDER BY c.ord) FROM land_cap_items c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}')), 'waived', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('node', c.node, 'kind', c.kind, 'rule', c.rule, 'commit', c.commit_sha, 'sha', c.sha, 'reason', c.reason, 'reading', c.reading, 'items', json(nullif((SELECT json_group_array(i.value ORDER BY i.i) FROM land_waived_items i WHERE i.queue = c.queue AND i.run = c.run AND i.ord = c.ord), '[]')))) ORDER BY c.ord) FROM land_waived c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}')), 'guard', (SELECT value FROM land_lists c WHERE c.queue=x.queue AND c.run=x.run AND c.kind='guard' AND c.ord=0), 'at', strftime('%Y-%m-%dT%H:%M:%SZ', x.at, 'unixepoch'))), coalesce(x.rest, '{}')) AS doc
FROM lands x
